const id = Symbol("id");
const base = { shared: true };
const item = Object.assign(Object.create(base), { 2: "b", name: "pen", 1: "a", [id]: 9 });
Object.defineProperty(item, "secret", { value: "x", enumerable: false });

const copy = { ...item };

console.log(Reflect.ownKeys(item).map(String).join(","));
console.log(Object.keys(copy).join(","));
console.log("shared" in copy, id in copy);
console.log(JSON.stringify(item));
